const listSubscriptionsToWake = `-- name: ListSubscriptionsToWake :many
SELECT id FROM billing.subscriptions
WHERE merchant_id = $1::uuid
  AND payment_method_id = $2::uuid
  AND collection_policy IN ('engine', 'nmi_schedule')
  AND (status = 'awaiting_method' OR (status = 'past_due' AND (next_retry_at IS NULL OR next_retry_at > $3::timestamptz)))
  AND deleted_at IS NULL
ORDER BY id
`

type ListSubscriptionsToWakeParams struct {
	MerchantID      uuid.UUID
	PaymentMethodID uuid.UUID
	Now             time.Time
}

// The delinquent memberships OpenRails collects that a replaced card retries
// at the next due pass, and those awaiting a card
// (subscriptions.WakeForReplacedMethod).
func (q *Queries) ListSubscriptionsToWake(ctx context.Context, arg ListSubscriptionsToWakeParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listSubscriptionsToWake, arg.MerchantID, arg.PaymentMethodID, arg.Now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markCanceledSubscriptionsSuperseded = `-- name: MarkCanceledSubscriptionsSuperseded :execrows
UPDATE billing.subscriptions
SET gateway_response = CASE WHEN jsonb_typeof(gateway_response) = 'object'
        THEN gateway_response || jsonb_build_object('superseded_at', current_timestamp, 'superseded_by_subscription_id', $3::text)
        ELSE jsonb_build_object('previous_gateway_response', gateway_response, 'superseded_at', current_timestamp, 'superseded_by_subscription_id', $3::text)
    END,
    updated_at = current_timestamp
WHERE subscriptions.merchant_id = $4::uuid AND customer_id = $1
  AND product_id = $2
  AND status = 'canceled'
  AND ($5::uuid IS NULL OR id != $5::uuid)
  AND deleted_at IS NULL
`

type MarkCanceledSubscriptionsSupersededParams struct {
	CustomerID   uuid.UUID
	ProductID    uuid.UUID
	SupersededBy *string
	MerchantID   uuid.UUID
	ExcludeID    *uuid.UUID
}

// Preserve canceled subscriptions for refund/chargeback correlation while
// stamping them superseded by the new activation (gateway_response patch).
func (q *Queries) MarkCanceledSubscriptionsSuperseded(ctx context.Context, arg MarkCanceledSubscriptionsSupersededParams) (int64, error) {
	result, err := q.db.Exec(ctx, markCanceledSubscriptionsSuperseded,
		arg.CustomerID,
		arg.ProductID,
		arg.SupersededBy,
		arg.MerchantID,
		arg.ExcludeID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

